/// <summary>
/// Example UPSPricingAttribute of table <c>InventDim</c> field ConfigId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventDimConfigId_Product extends UPSPricingAttributeInventDim_Product implements UPSIPricingAttribute
{
}

Method.Source:
public str getName() 
{
    return fieldPName(InventDim, configid);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    EcoResConfiguration config;
    while select Name from config
        group by Name
    {
        ret.add(config.Name);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, ConfigId));
    qbr.value(queryValue(_value));
}
